 const pick=$('work574Recipients'),aud=$('work574Audience'),search=$('work574RecipientSearch'),all=$('work574RecipientAll'),count=$('work574RecipientCount'),send=$('work574SendNow');let list=[],chosen=new Set(),loaded=false,sending=false,lockedAfterError=false;
