 getRecipients579().then(p=>{if(!current())return;list=p;loaded=true;drawChoices()}).catch(e=>{if(current()){count.textContent=L('Recipients unavailable: ','प्राप्तकर्ता उपलब्ध नहीं: ')+e.message;send.disabled=true}});
