  const run={who,total:ids.length,saved:0,phase:'sending',reviewed:false};noticeRun580=run;sending=true;aud.disabled=true;search.disabled=true;update();let saved=0;
  try{for(let i=0;i<payload.length;i+=200){if(!current())throw Error('Page changed; check response report before retrying');const part=payload.slice(i,i+200),rows=await result(db().from('ldm574_messages').insert(part).select('id'));if(rows.length!==part.length)throw Error('Message save count mismatch');saved+=rows.length;run.saved=saved;notifyNotice580();if(current())msg(status(),`${saved}/${ids.length} ${L('messages saved','संदेश सुरक्षित')}`)}run.phase='complete';notifyNotice580();if(current()){$('work574Title').value='';$('work574MessageText').value='';$('work574TaskLink').value='';delete pick.dataset.remindRecipient;chosen.clear();aud.value='custom';search.value='';drawChoices()}}
