async function studentRegister(t){const host=$('work574Body'),who=uid(),tag=++pageTicket;if(!host||!t.class_scope||t.route!=='students'||!canOpenLegacy(t))return;host.dataset.work579Tab='register';host.textContent='Loading…';try{const rows=await readPages('students','id,admission_no,student_name,father_name,roll_no,class_name',q=>q.eq('class_name',t.class_scope).order('id'));if(!host.isConnected||uid()!==who||tag!==pageTicket)return;const keys=['student_name','father_name','roll_no','admission_no','class_name'];let order='student_name',dir=1;const drafts=new Map();host.innerHTML=`<button id="work574Back">Back to work</button><p>Class: ${E(t.class_scope)} • Existing class permissions apply. Only basic name / father / roll fields.</p><input id="work574StudentSearch" placeholder="Name / father / roll / admission"><div id="work574Students"></div>`;$('work574Back').onclick=loadCenter;function draw(){const h=$('work574Students'),old=h.querySelector('.work574Scroll'),x=old?.scrollLeft||0,y=old?.scrollTop||0,q=$('work574StudentSearch').value.toLowerCase();const show=rows.filter(r=>keys.some(k=>String((drafts.get(r.id)||r)[k]||'').toLowerCase().includes(q))).sort((a,b)=>dir*String((drafts.get(a.id)||a)[order]??'').localeCompare(String((drafts.get(b.id)||b)[order]??''),undefined,{numeric:true}));h.innerHTML=`<div class="work574Scroll"><table class="work574Table work574StudentTable noAutoSort"><thead><tr><th>S.N.</th>${keys.map(k=>`<th>${E(k.replaceAll('_',' '))}<button data-k="${k}" data-d="1">↑</button><button data-k="${k}" data-d="-1">↓</button></th>`).join('')}<th>Save</th></tr></thead><tbody>${show.map((r,i)=>{let d=drafts.get(r.id)||r;return `<tr data-id="${E(r.id)}"><td>${i+1}</td>${keys.map((k,j)=>`<td>${j<3?`<input data-field="${k}" value="${E(d[k])}" maxlength="160">`:E(r[k])}</td>`).join('')}<td><button data-save>Save</button><small data-row-status></small></td></tr>`}).join('')}</tbody></table></div><div class="work574BottomScroll"><div></div></div><small>${show.length} records</small>`;syncScroll(h,x,y);h.querySelectorAll('[data-k]').forEach(b=>b.onclick=()=>{order=b.dataset.k;dir=Number(b.dataset.d);draw()});h.querySelectorAll('[data-field]').forEach(i=>i.oninput=()=>{const id=i.closest('tr').dataset.id,r=rows.find(x=>x.id===id);drafts.set(id,{...(drafts.get(id)||r),[i.dataset.field]:i.value})});h.querySelectorAll('[data-save]').forEach(b=>b.onclick=async()=>{if(b.disabled||!canOpenLegacy(t)||uid()!==who||tag!==pageTicket)return;const tr=b.closest('tr'),id=tr.dataset.id,r=rows.find(x=>x.id===id),d=drafts.get(id)||r,changes={student_name:String(d.student_name||'').trim(),father_name:String(d.father_name||'').trim(),roll_no:String(d.roll_no||'').trim()};if(!changes.student_name)return msg(tr.querySelector('[data-row-status]'),'Name required',true);b.disabled=true;try{const check=await result(db().from('ldm574_tasks').select('id,recipient,access_mode,deadline,revoked_at').eq('id',t.id).eq('recipient',who).is('revoked_at',null));if(check.length!==1||uid()!==who||tag!==pageTicket||!canOpenLegacy(check[0]))throw Error('Task revoked, expired or no longer task-only');const adm=await result(db().rpc('v64_teacher_update_student_basic',{p_student_id:id,p_changes:changes}));if(!adm)throw Error('No admission returned');Object.assign(r,changes);drafts.delete(id);try{await result(db().rpc('v64_propagate_student_master',{p_admission_no:adm}));msg(tr.querySelector('[data-row-status]'),'Saved & synced')}catch(e){msg(tr.querySelector('[data-row-status]'),'Saved; sync failed: '+e.message,true)}}catch(e){msg(tr.querySelector('[data-row-status]'),e.message,true)}finally{b.disabled=false}})}$('work574StudentSearch').oninput=draw;draw()}catch(e){if(host.isConnected&&uid()===who&&tag===pageTicket)host.textContent=e.message}}
